fn append(a: &Vec<i32>, b: i32) -> Vec<i32> {
    // Allocate a new vector with enough capacity for all existing elements plus one
    let mut result = Vec::with_capacity(a.len() + 1);
    // Copy all elements from the original vector
    result.extend_from_slice(a);
    // Append the new element
    result.push(b);
    result
}

